import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD: Long = 998244353L

fun modAdd(a: Long, b: Long): Long {
    var res = a + b
    if (res >= MOD) res -= MOD
    return res
}

fun modMul(a: Long, b: Long): Long {
    return (a * b) % MOD
}

fun matMul(a: Array<LongArray>, b: Array<LongArray>): Array<LongArray> {
    val n = a.size
    val res = Array(n) { LongArray(n) }
    for (i in 0 until n) {
        for (k in 0 until n) {
            if (a[i][k] == 0L) continue
            val aik = a[i][k]
            for (j in 0 until n) {
                if (b[k][j] == 0L) continue
                res[i][j] = (res[i][j] + aik * b[k][j]) % MOD
            }
        }
    }
    return res
}

fun matPow(base: Array<LongArray>, exp: Long): Array<LongArray> {
    val n = base.size
    var e = exp
    var result = Array(n) { LongArray(n) }
    for (i in 0 until n) result[i][i] = 1L
    var cur = base
    while (e > 0) {
        if ((e and 1L) != 0L) result = matMul(result, cur)
        cur = matMul(cur, cur)
        e = e shr 1
    }
    return result
}

