        for (ch in word) {
            val c = ch - 'a'
            if (trie[cur].next[c] == -1) {
                trie[cur].next[c] = trie.size
                trie.add(Node())
            }
            cur = trie[cur].next[c]
        }
        trie[cur].terminalMask = trie[cur].terminalMask or (1 shl idx)
    }

    for ((i, w) in words.withIndex()) addWord(w, i)

    val trieSize = trie.size

    // Precompute transitions for each state and letter
    val trans = Array(trieSize) { IntArray(26) }
    for (s in 0 until trieSize) {
        for (c in 0 until 26) {
            var cur = s
