                cur = 0
            }
            val nx = trie[cur].next[c]
            trans[s][c] = if (nx == -1) 0 else nx
        }
    }

    val totalStates = trieSize * trieSize
    fun id(a: Int, b: Int): Int = a * trieSize + b

    val T = Array(totalStates) { LongArray(totalStates) }

