    val wordByLen = Array(maxLen + 1) { mutableListOf<Int>() }
    for (i in 0 until n) {
        val len = words[i].length
        wordByLen[len].add(i)
    }

    // For each pair of states (a,b), compute transitions
    for (a in 0 until trieSize) {
        for (b in 0 until trieSize) {
            val fromId = id(a, b)
            // For each possible length up to maxLen, we try all combinations of words
            // but we must ensure the resulting letters are consistent.
            // We'll brute force all pairs of words (wa, wb) and check if they can align.
            for (len in 1..maxLen) {
                val listA = wordByLen[len]
                val listB = wordByLen[len]
                if (listA.isEmpty() || listB.isEmpty()) continue
                for (ia in listA) {
                    val wa = words[ia]
                    // simulate top path
                    var sa = a
                    var okA = true
                    for (ch in wa) {
                        val c = ch - 'a'
                        sa = trans[sa][c]
                        if (((trie[sa].terminalMask shr ia) and 1) == 0) {
                            okA = false
                            break
                        }
                    }
                    if (!okA) continue
                    for (ib in listB) {
                        val wb = words[ib]
                        // check consistency of letters
                        var consistent = true
                        for (k in 0 until len) {
                            if (wa[k] != wb[k]) {
                                consistent = false
                                break
                            }
                        }
                        if (!consistent) continue
                        var sb = b
                        var okB = true
                        for (ch in wb) {
                            val c = ch - 'a'
                            sb = trans[sb][c]
                            if (((trie[sb].terminalMask shr ib) and 1) == 0) {
                                okB = false
                                break
                            }
                        }
                        if (!okB) continue
                        val toId = id(sa, sb)
                        T[fromId][toId] = (T[fromId][toId] + 1L) % MOD
                    }
                }
            }
        }
    }

    val Tm = matPow(T, m)

    val startId = id(0, 0)
    var ans = 0L
    for (i in 0 until totalStates) {
        ans = (ans + Tm[startId][i]) % MOD
    }

    println(ans)

