import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD: Long = 998244353L

fun modAdd(a: Long, b: Long): Long {
    var res = a + b
    if (res >= MOD) res -= MOD
    return res
}

fun modMul(a: Long, b: Long): Long = (a * b) % MOD

fun modPow(base: Long, exp: Long): Long {
    var b = base
    var e = exp
    var res = 1L
    while (e > 0) {
        if ((e and 1L) != 0L) res = modMul(res, b)
        b = modMul(b, b)
        e = e shr 1
    }
    return res
}

fun matMul(a: Array<LongArray>, b: Array<LongArray>): Array<LongArray> {
    val n = a.size
    val res = Array(n) { LongArray(n) }
    for (i in 0 until n) {
        for (k in 0 until n) {
            if (a[i][k] == 0L) continue
            val aik = a[i][k]
            for (j in 0 until n) {
                if (b[k][j] == 0L) continue
                res[i][j] = (res[i][j] + aik * b[k][j]) % MOD
            }
        }
    }
    return res
}

fun matVecMul(mat: Array<LongArray>, vec: LongArray): LongArray {
    val n = mat.size
    val res = LongArray(n)
    for (i in 0 until n) {
        var sum = 0L
        val row = mat[i]
        for (j in 0 until n) {
            if (row[j] == 0L || vec[j] == 0L) continue
            sum = (sum + row[j] * vec[j]) % MOD
        }
        res[i] = sum
    }
    return res
}

fun matPow(mat: Array<LongArray>, exp: Long): Array<LongArray> {
    val n = mat.size
    var e = exp
    var base = mat
    var res = Array(n) { LongArray(n) }
    for (i in 0 until n) res[i][i] = 1L
    while (e > 0) {
        if ((e and 1L) != 0L) res = matMul(res, base)
        base = matMul(base, base)
        e = e shr 1
    }
    return res
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toLong()

    val words = ArrayList<String>()
    var maxLen = 0
    repeat(n) {
        val w = br.readLine().trim()
        words.add(w)
        if (w.length > maxLen) maxLen = w.length
    }

    val L = maxLen
    val stateCount = 1 shl L

    // Precompute transitions for one hint (same for both)
    val trans = Array(stateCount) { LongArray(stateCount) }

    // For each state, we need to know which suffixes are words
    val isWord = BooleanArray(L + 1)
    val wordByLen = Array(L + 1) { mutableListOf<String>() }
    for (w in words) {
        val len = w.length
        wordByLen[len].add(w)
    }

    // Since words are short (<=5), we can brute force transitions
    // State is bitmask of length L: bit 0 is most recent position (length 1 suffix),
    // bit k-1 corresponds to suffix of length k.
    // But we only need to know which suffix lengths are words.
    // For each state, we know which suffix lengths are words by checking bits.
    // However, we also must ensure that the sequence of segments covers all positions:
    // This is enforced globally by DP; locally, any word placement is allowed.

    // Precompute for each state which suffix lengths are words
    val wordSuffixMask = IntArray(stateCount)
    for (mask in 0 until stateCount) {
        var wmask = 0
        for (len in 1..L) {
            if ((mask and (1 shl (len - 1))) != 0) {
                // suffix of length len exists; check if any dictionary word has this length
                if (wordByLen[len].isNotEmpty()) {
                    wmask = wmask or (1 shl (len - 1))
                }
            }
        }
        wordSuffixMask[mask] = wmask
    }

    // But we actually need transitions based on letters; however, the problem only cares
    // about counts of strings where segments form dictionary words, not specific letters.
    // For counting, we can treat each word as abstract segment of length len, independent of letters.
    // Thus, for each position, we choose a word length that ends here; the number of choices is
    // number of words of that length. This is equivalent to compositions of m with parts in lengths
    // of words, weighted by counts. That is just linear recurrence of order L.
    // So we don't need bitmask states; we can use DP on length with recurrence:
    // f[k] = sum over words w of f[k - |w|].
    // This is simple linear recurrence; we can exponentiate companion matrix.

    // Build recurrence coefficients
    val coeff = LongArray(L + 1) // coeff[len] = number of words of length len
    for (len in 1..L) {
        coeff[len] = wordByLen[len].size.toLong() % MOD
    }

    // If there is no way to cover length m with segments, answer is 0
    // But recurrence will handle that.

    // Build companion matrix of size L:
    // [c1 c2 ... cL]
    // [1  0  ... 0 ]
    // [0  1  ... 0 ]
    // ...
    val size = L
    val comp = Array(size) { LongArray(size) }
    // first row
    for (i in 0 until size) {
        comp[0][i] = coeff[i + 1] % MOD
    }
    // subdiagonal
    for (i in 1 until size) {
        comp[i][i - 1] = 1L
    }

    fun computeF(len: Long): Long {
        if (len == 0L) return 1L
        if (len < 0L) return 0L
        if (len <= size.toLong()) {
            // simple DP
            val f = LongArray(len.toInt() + 1)
            f[0] = 1L
            for (k in 1..len.toInt()) {
                var sum = 0L
                for (l in 1..L) {
                    if (l > k) break
                    if (coeff[l] == 0L) continue
                    sum = (sum + coeff[l] * f[k - l]) % MOD
                }
                f[k] = sum
            }
            return f[len.toInt()]
        }
        // initial vector: [f[L], f[L-1], ..., f[1]]
        val init = LongArray(size)
        val f = LongArray(size + 1)
        f[0] = 1L
        for (k in 1..size) {
            var sum = 0L
            for (l in 1..L) {
                if (l > k) break
                if (coeff[l] == 0L) continue
                sum = (sum + coeff[l] * f[k - l]) % MOD
            }
            f[k] = sum
        }
        for (i in 0 until size) {
            init[i] = f[size - i].toLong()
        }
        val power = len - size
        val mat = matPow(comp, power)
        val resVec = matVecMul(mat, init)
        return resVec[0]
    }

    val fM = computeF(m)
    val ans = modMul(fM, fM)
    println(ans % MOD)
}

