fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    var st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toLong()

    val words = ArrayList<String>()
    var maxLen = 0
    repeat(n) {
        val w = br.readLine().trim()
        words.add(w)
        if (w.length > maxLen) maxLen = w.length
    }

    // Build alphabet from words
    val alphaSet = HashSet<Char>()
    for (w in words) for (c in w) alphaSet.add(c)
    val alpha = alphaSet.toCharArray()
    val alphaIndex = HashMap<Char, Int>()
    for (i in alpha.indices) alphaIndex[alpha[i]] = i
    val sigma = alpha.size

    // Build Aho-Corasick automaton
    data class Node(
        val next: IntArray,
        var link: Int,
        var outMask: Int
    )

    val nodes = ArrayList<Node>()
    fun newNode(): Int {
        val nxt = IntArray(sigma) { -1 }
        nodes.add(Node(nxt, 0, 0))
        return nodes.size - 1
    }

    newNode() // root 0

    for ((idx, w) in words.withIndex()) {
        var v = 0
        for (ch in w) {
            val c = alphaIndex[ch]!!
            if (nodes[v].next[c] == -1) {
                val u = newNode()
                nodes[v].next[c] = u
            }
            v = nodes[v].next[c]
        }
        nodes[v].outMask = nodes[v].outMask or (1 shl idx)
    }

    // Build suffix links
    val q: java.util.ArrayDeque<Int> = java.util.ArrayDeque()
    for (c in 0 until sigma) {
        val u = nodes[0].next[c]
        if (u != -1) {
            nodes[u].link = 0
            q.add(u)
        } else {
            nodes[0].next[c] = 0
        }
    }
    while (!q.isEmpty()) {
        val v = q.removeFirst()
        val link = nodes[v].link
        nodes[v].outMask = nodes[v].outMask or nodes[link].outMask
        for (c in 0 until sigma) {
            var u = nodes[v].next[c]
            if (u != -1) {
                nodes[u].link = nodes[link].next[c]
                q.add(u)
            } else {
                nodes[v].next[c] = nodes[link].next[c]
            }
        }
    }

    val acStates = nodes.size

    // Precompute transitions for each state and letter
    val trans = Array(acStates) { IntArray(sigma) }
    val outMask = IntArray(acStates)
    for (i in 0 until acStates) {
        outMask[i] = nodes[i].outMask
        for (c in 0 until sigma) {
            trans[i][c] = nodes[i].next[c]
        }
    }

    // DP state: (acState, maskTop, maskBottom)
    val maxMask = 1 shl n
    val stateId = HashMap<Triple<Int, Int, Int>, Int>()
    val states = ArrayList<Triple<Int, Int, Int>>()

    fun getStateId(ac: Int, mt: Int, mb: Int): Int {
        val key = Triple(ac, mt, mb)
        val id = stateId[key]
        if (id != null) return id
        val nid = states.size
        states.add(key)
        stateId[key] = nid
        return nid
    }

    // BFS over states
    val queue: java.util.ArrayDeque<Int> = java.util.ArrayDeque()
    val startId = getStateId(0, 0, 0)
    queue.add(startId)

    while (!queue.isEmpty()) {
        val id = queue.removeFirst()
        val (ac, mt, mb) = states[id]
        for (c in 0 until sigma) {
            val nac = trans[ac][c]
            val om = outMask[nac]
            val nmt = mt or om
            val nmb = mb or om
            val nid = getStateId(nac, nmt, nmb)
            if (nid >= states.size - 1) {
                queue.add(nid)
            }
        }
    }

    val S = states.size
    val mat = Array(S) { LongArray(S) }

    for (id in 0 until S) {
        val (ac, mt, mb) = states[id]
        for (c in 0 until sigma) {
            val nac = trans[ac][c]
            val om = outMask[nac]
            val nmt = mt or om
            val nmb = mb or om
            val nid = stateId[Triple(nac, nmt, nmb)]!!
            mat[id][nid] = (mat[id][nid] + 1L) % MOD
        }
    }

    val matPowM = matPow(mat, m)

    var ans = 0L
    val startVecIndex = startId
    for (id in 0 until S) {
        val (_, mt, mb) = states[id]
        if (mt != 0 && mb != 0) {
            ans = (ans + matPowM[startVecIndex][id]) % MOD
        }
    }

    println(ans % MOD)
}
